{"probes": [{"obligation_id": "OB-009", "strategy": "example", "rationale": "Comma-separated amount '12,34' is a string Decimal cannot parse and raises decimal.InvalidOperation internally; the clause requires this be converted to ValueError, not propagate as InvalidOperation.", "code": "import pytest
import decimal
import impl


@pytest.mark.parametrize("bad_amount", ['', 'abc', '1.2.3', '12,34', '$1.00', '1 000.00'])
def test_unparseable_amount_raises_value_error_not_invalid_operation(bad_amount):
    with pytest.raises(ValueError):
        impl.format_amount(bad_amount, 'USD', {'USD': 2})
    # explicitly ensure InvalidOperation never escapes
    try:
        impl.format_amount(bad_amount, 'USD', {'USD': 2})
    except decimal.InvalidOperation:
        pytest.fail("decimal.InvalidOperation propagated instead of ValueError")
    except ValueError:
        pass
